[CmdletBinding()]
param([Parameter(Position=0)][string]$InputPath,[ValidateRange(-1.0,1.0)][double]$DualMonoCorrelation=0.995,[ValidateRange(-1.0,1.0)][double]$NegativeCorrelation=-0.90,[ValidateRange(0.0,[double]::MaxValue)][double]$ImbalanceDb=3,[switch]$Json,[string]$Output,[switch]$Help)
. "$PSScriptRoot/lib/Common.ps1";. "$PSScriptRoot/lib/FFmpeg.ps1"
if($Help){'stereotruth BETA - detect dual-mono, polarity and imbalance candidates';'Usage: .\stereotruth.ps1 INPUT [-DualMonoCorrelation X] [-NegativeCorrelation X] [-ImbalanceDb DB] [-Json] [-Output path]';exit 0};if(-not $InputPath){[Console]::Error.WriteLine('input required');exit 2};Assert-CDLDependencies;if(-not(Test-Path -LiteralPath $InputPath -PathType Leaf)){[Console]::Error.WriteLine("unreadable input: $InputPath");exit 2};$p=(Resolve-Path -LiteralPath $InputPath).Path;Assert-CDLReportTarget -Output $Output -Sources @($p);$ch=Get-CDLProbeValue $p channels;if($ch -ne '2'){[Console]::Error.WriteLine('stereotruth requires exactly two decoded channels');exit 2}
$windows=@(Get-CDLPhaseSamples $p);$count=$windows.Count;$dual=if($count){@($windows|Where-Object{$_.correlation -ge $DualMonoCorrelation}).Count/$count}else{0};$neg=if($count){@($windows|Where-Object{$_.correlation -le $NegativeCorrelation}).Count/$count}else{0};$mean=if($count){($windows|Measure-Object correlation -Average).Average}else{0}
$lines=& ffmpeg -hide_banner -loglevel error -i $p -af 'astats=metadata=1:reset=0,ametadata=print:file=-' -f null - 2>&1;$lr=$null;$rr=$null;foreach($line in $lines){$s="$line";if($null -eq $lr -and $s -match 'lavfi\.astats\.1\.RMS_level=([-0-9.]+)'){$lr=[double]$Matches[1]};if($null -eq $rr -and $s -match 'lavfi\.astats\.2\.RMS_level=([-0-9.]+)'){$rr=[double]$Matches[1]}};$bal=if($null -ne $lr -and $null -ne $rr){[math]::Abs($lr-$rr)}else{0};$find=@();if($dual -ge .9){$find+=New-CDLFinding 'dual_mono_candidate' "$([math]::Round($dual*100,1))% of measured phase windows meet dual-mono threshold"};if($neg -ge .5){$find+=New-CDLFinding 'polarity_inversion_candidate' 'sustained strongly negative correlation observed'};if($bal -ge $ImbalanceDb){$find+=New-CDLFinding 'channel_imbalance' "RMS balance difference $bal dB exceeds $ImbalanceDb dB"}
$status=if($find.Count){'review'}else{'ok'};$report=[ordered]@{tool='stereotruth';version=$script:CDLVersion;generated_utc=[DateTime]::UtcNow.ToString('yyyy-MM-ddTHH:mm:ssZ');inputs=@($p);dependencies=Get-CDLVersions;options=[ordered]@{dual_mono_correlation=$DualMonoCorrelation;negative_correlation=$NegativeCorrelation;imbalance_db=$ImbalanceDb};measurements=[ordered]@{window_count=$count;mean_correlation=$mean;dual_mono_window_ratio=$dual;negative_window_ratio=$neg;left_rms_db=$lr;right_rms_db=$rr;rms_balance_db=$bal};findings=$find;status=$status};Write-CDLReport $report -Json:$Json -Output $Output -Text "stereotruth BETA: mean_corr=$mean balance_db=$bal status=$status";if($find.Count){exit 1};exit 0
